import React, { useState, useEffect, useMemo } from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Legend, Cell, CartesianGrid, PieChart, Pie } from "recharts";
import { ArrowTrendingUpIcon } from "@heroicons/react/24/solid";

const COLORS = ['#4ade80', '#60a5fa', '#f472b6', '#fbbf24', '#a78bfa'];

function getMonthsRemaining(deadline) {
  const now = new Date();
  const end = new Date(deadline);
  return Math.max(
    1,
    (end.getFullYear() - now.getFullYear()) * 12 + (end.getMonth() - now.getMonth())
  );
}

function getMonthlySavings(goal) {
  const months = getMonthsRemaining(goal.deadline);
  const amountLeft = Math.max(goal.amount - (goal.saved || 0), 0);
  return +(amountLeft / months).toFixed(2);
}

export default function Overview({ goals = [], income = { monthlyDisposableIncome: 0 }, currentSavings = 0, plan = null }) {
  const [chartData, setChartData] = useState([]);

  // Calculate chart data
  useEffect(() => {
    try {
      if (!goals?.length || !plan) {
        setChartData([]);
        return;
      }

      const newChartData = goals.map(goal => {
        if (!goal?.id) return null;

        const monthlyAllocation = plan.monthlyAllocations?.[goal.id] || 0;
        const totalAllocation = plan.totalAllocations?.[goal.id] || 0;
        const targetAmount = goal.targetAmount || 0;
        const remainingSavings = Math.max(0, targetAmount - totalAllocation);

        return {
          name: goal.name || 'Unnamed Goal',
          monthlyAllocation,
          totalAllocation,
          targetAmount,
          remainingSavings
        };
      }).filter(Boolean); // Remove any null entries

      if (newChartData.length > 0) {
        // Add total row
        const totalMonthlyAllocation = newChartData.reduce((sum, item) => sum + (item.monthlyAllocation || 0), 0);
        const totalAllocation = newChartData.reduce((sum, item) => sum + (item.totalAllocation || 0), 0);
        const totalTargetAmount = newChartData.reduce((sum, item) => sum + (item.targetAmount || 0), 0);
        const totalRemainingSavings = newChartData.reduce((sum, item) => sum + (item.remainingSavings || 0), 0);

        newChartData.push({
          name: "Total",
          monthlyAllocation: totalMonthlyAllocation,
          totalAllocation: totalAllocation,
          targetAmount: totalTargetAmount,
          remainingSavings: totalRemainingSavings
        });
      }

      setChartData(newChartData);
    } catch (error) {
      console.error('Error calculating chart data:', error);
      setChartData([]);
    }
  }, [goals, plan]);

  // Calculate pie chart data
  const pieChartData = useMemo(() => {
    try {
      if (!chartData?.length) return [];

      return chartData
        .filter(item => item.name !== "Total")
        .map(item => ({
          name: item.name,
          value: item.totalAllocation || 0
        }))
        .filter(item => item.value > 0);
    } catch (error) {
      console.error('Error calculating pie chart data:', error);
      return [];
    }
  }, [chartData]);

  // Calculate total savings distribution
  const totalSavingsDistribution = useMemo(() => {
    try {
      if (!plan?.totalSavingsNeeded || !currentSavings) return [];

      const totalNeeded = plan.totalSavingsNeeded;
      const saved = currentSavings;
      const remaining = Math.max(0, totalNeeded - saved);

      return [
        { name: "Total Saved", value: saved },
        { name: "Remaining", value: remaining }
      ].filter(item => item.value > 0);
    } catch (error) {
      console.error('Error calculating total savings distribution:', error);
      return [];
    }
  }, [plan?.totalSavingsNeeded, currentSavings]);

  // Calculate total target amount
  const totalTargetAmount = goals?.reduce((sum, goal) => sum + (goal.targetAmount || 0), 0) || 0;

  // Calculate shortfall
  const shortfall = useMemo(() => {
    try {
      if (!plan?.totalMonthlyNeeded || !income?.monthlyDisposableIncome) return 0;
      return Math.max(0, plan.totalMonthlyNeeded - income.monthlyDisposableIncome);
    } catch (error) {
      console.error('Error calculating shortfall:', error);
      return 0;
    }
  }, [plan?.totalMonthlyNeeded, income?.monthlyDisposableIncome]);

  // Calculate percentages for pie chart labels
  const totalMonthly = plan?.totalMonthlyNeeded || 0;

  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white p-4 rounded-lg shadow-lg border border-gray-200">
          <p className="font-semibold">{label}</p>
          {payload.map((entry, index) => (
            <p key={index} style={{ color: entry.color }}>
              {entry.name}: ${entry.value.toLocaleString()}
            </p>
          ))}
        </div>
      );
    }
    return null;
  };

  if (!goals?.length) {
    return (
      <div className="p-6">
        <div className="text-center text-gray-500">
          No goals found. Add some goals to see your savings plan.
        </div>
      </div>
    );
  }

  return (
    <div className="p-6">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Bar Chart */}
        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold mb-4">Monthly Savings Allocation</h2>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis 
                  dataKey="name" 
                  angle={-45} 
                  textAnchor="end" 
                  height={100}
                  interval={0}
                />
                <YAxis />
                <Tooltip content={<CustomTooltip />} />
                <Legend />
                <Bar dataKey="monthlyAllocation" name="Monthly Allocation" fill="#4ade80" radius={[4, 4, 0, 0]} />
                <Bar dataKey="totalAllocation" name="Total Allocation" fill="#60a5fa" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Pie Chart */}
        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold mb-4">Total Savings Distribution</h2>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={totalSavingsDistribution}
                  dataKey="value"
                  nameKey="name"
                  cx="50%"
                  cy="50%"
                  outerRadius={100}
                  label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                >
                  {totalSavingsDistribution.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mt-6">
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-sm font-medium text-gray-500">Total Target Amount</h3>
          <p className="text-2xl font-semibold mt-2">${totalTargetAmount.toLocaleString()}</p>
        </div>
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-sm font-medium text-gray-500">Monthly Savings Needed</h3>
          <p className="text-2xl font-semibold mt-2">${(plan?.totalMonthlyNeeded || 0).toLocaleString()}</p>
        </div>
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-sm font-medium text-gray-500">Monthly Shortfall</h3>
          <p className="text-2xl font-semibold mt-2 text-red-500">${shortfall.toLocaleString()}</p>
        </div>
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-sm font-medium text-gray-500">Total Saved</h3>
          <p className="text-2xl font-semibold mt-2">${currentSavings.toLocaleString()}</p>
        </div>
      </div>
    </div>
  );
}
